def backfill_batches(apps, schema_editor):
    """Give every existing roll a batch, the same way new rolls get one:
    a processed/split roll keeps its parent's batch, otherwise one batch per
    lot number. Codes follow the BAT series (OSCAR-GRY-<year>-<n>)."""
    LotTaka = apps.get_model("inventory", "LotTaka")
    Batch = apps.get_model("inventory", "Batch")
